local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

local CanvasGroup = CS.UnityEngine.CanvasGroup
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleStoryQuestComponent)

---@class UIPolePlotEndRewardPopupRewardNode
---@field ImgDebris                     	UnityEngine.RectTransform               
---@field PointGroup                    	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform                                 
local UIPolePlotEndRewardPopupRewardNode = Class("UIPolePlotEndRewardPopupRewardNode")
function UIPolePlotEndRewardPopupRewardNode:__init() 
    self._data = nil
    self._drawReardCb = nil
end

function UIPolePlotEndRewardPopupRewardNode:__delete()
    self._data = nil
    self._drawReardCb = nil
end

function UIPolePlotEndRewardPopupRewardNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrawReward))
end

function UIPolePlotEndRewardPopupRewardNode:Start()
end

function UIPolePlotEndRewardPopupRewardNode:Refresh(id, drawReardCb)
    if not id then
        return
    end
    local vo = QuestConfMgr:GetInstance():GetQuestRoleStoryRewardVo(id)
    if not vo then
        return
    end

    self._drawReardCb = drawReardCb
    self._data = vo
    self:FillSelf()
end

function UIPolePlotEndRewardPopupRewardNode:FillSelf()
    CfUtils.FillText(self.TxtTitle, self._data.name)

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = QuestConfMgr:GetInstance():GetRewardDataById(self._data.id)
        scr:FreshBaseUI(t)
    end

    local isDraw = QuestConfMgr:GetInstance():IsDrawRoleQuestRewardById(self._data.id)
    local isCanDraw = QuestConfMgr:GetInstance():IsCanDrawRoleQuestRewardById(self._data.id)

    CfUtils.SetUISwitchImage(self.Normal.transform:Find("ImgBg/ImgInk1"), isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.Normal.transform:Find("ImgBg/ImgInk2"), isCanDraw and 2 or 1)

    KTool.SetActive(self.FinishGroup, isDraw)
    KTool.SetActive(self.FontStyleButton, isCanDraw)
    KTool.SetActive(self.TxtOngoing, ((not isCanDraw) and (not isDraw)))
end

function UIPolePlotEndRewardPopupRewardNode:OnDrawReward()
    local isDraw = QuestConfMgr:GetInstance():IsDrawRoleQuestRewardById(self._data.id)
    if isDraw then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    end
    local isCanDraw = QuestConfMgr:GetInstance():IsCanDrawRoleQuestRewardById(self._data.id)
    if not isCanDraw then
        GameUtils.Toast(localize("未满足领取条件"))
        return
    end

    comp:DrawRewardReq(self._data.id, function()
        if self._drawReardCb then
            self._drawReardCb()
        end
    end)
end

function UIPolePlotEndRewardPopupRewardNode:PlayAni(name)
    CfUtils.PlayAnimator(self.controller.gameObject, name)
end

function UIPolePlotEndRewardPopupRewardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIPolePlotEndRewardPopupRewardNode
